with base as (select *, length(status) as status_length from subscriptions where end_date > date '2023-07-25') select id, customer_id, plan, status, ntile(5) over (order by status_length desc, id) as status_length_bucket, sum(monthly_fee) over (partition by customer_id order by start_date, id rows between unbounded preceding and current row) as cumulative_monthly_fee, ntile(4) over (partition by plan, customer_id order by status_length, id) as status_length_bucket_2 from base where customer_id in (16, 40)
